.pstrip::after{content:"";position:absolute;inset:0;background:radial-gradient(60% 150% at 88% 50%,rgba(226,16,25,.22),transparent 62%)}
.pstrip-in{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:26px;flex-wrap:wrap;padding-top:28px;padding-bottom:28px}
.ps-l{display:flex;align-items:center;gap:16px;min-width:0}
.ps-ic{width:54px;height:54px;border-radius:13px;background:rgba(226,16,25,.16);border:1px solid rgba(226,16,25,.44);display:grid;place-items:center;color:var(--red-l);flex-shrink:0}
.ps-ic svg{width:25px;height:25px}
.pstrip h3{font-size:clamp(19px,2.3vw,25px);color:#fff;text-transform:uppercase;line-height:1.1}
.pstrip p{font-size:14.5px;color:#9db0bd;margin-top:6px;max-width:58ch}
.veh-more{text-align:center;margin-top:30px}
.veh-more a{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:800;font-size:14px;letter-spacing:.04em;text-transform:uppercase;color:var(--ink);
 background:#fff;border:1px solid var(--line);border-radius:11px;padding:14px 22px;box-shadow:var(--sh);transition:.2s}
.veh-more a:hover{transform:translateY(-3px);border-color:var(--red);color:var(--red)}
.veh-more svg{width:17px;height:17px}
@media(max-width:720px){
.pstrip-in{flex-direction:column;align-items:flex-start}
.pstrip .btn{width:100%;justify-content:center}
}

/* ===== THANK YOU PAGE ===== */
.ty{position:relative;overflow:hidden;background:radial-gradient(120% 130% at 80% 0%,#17222c,var(--ink) 60%);color:#eaf2f6;
 padding-top:clamp(46px,6vw,82px);padding-bottom:clamp(54px,6.5vw,88px)}
.ty-in{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:clamp(32px,5vw,62px);align-items:center}
.ty-in>*{min-width:0}
.ty-tick{width:70px;height:70px;border-radius:50%;background:rgba(226,16,25,.14);border:1px solid rgba(226,16,25,.45);
 display:grid;place-items:center;color:var(--red-l);margin-bottom:22px;animation:pulseTick 2.4s ease-in-out infinite}
.ty-tick svg{width:32px;height:32px}
@keyframes pulseTick{0%,100%{box-shadow:0 0 0 0 rgba(226,16,25,.42)}70%{box-shadow:0 0 0 18px rgba(226,16,25,0)}}
.ty h1{font-size:clamp(30px,4.6vw,52px);color:#fff;text-transform:uppercase;margin-top:16px;line-height:1.02}
.ty .sub{color:#a9b9c3;font-size:clamp(15px,1.6vw,18px);margin-top:18px;max-width:46ch}
.ty-btns{display:flex;gap:14px;flex-wrap:wrap;margin-top:30px}
.ty-mail{margin-top:18px}
.ty-mail a{display:inline-flex;align-items:center;gap:9px;font-size:14.5px;color:#b9c7d1;font-weight:600}
.ty-mail a:hover{color:#fff}
.ty-mail svg{width:17px;height:17px;color:var(--red-l)}

.ty-next{position:relative;width:100%;max-width:430px;justify-self:end;border-radius:18px;
 background-color:#10181f;
 background-image:radial-gradient(circle at 11px 11px,#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),
  radial-gradient(circle at calc(100% - 11px) 11px,#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),
  radial-gradient(circle at 11px calc(100% - 11px),#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),
  radial-gradient(circle at calc(100% - 11px) calc(100% - 11px),#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),
  linear-gradient(170deg,#1d2832,#10181f 60%,#0b1117);
 background-repeat:no-repeat;border:1px solid rgba(255,255,255,.17);
 box-shadow:0 44px 96px -34px rgba(0,0,0,.95),inset 0 1px 0 rgba(255,255,255,.12)}
.ty-next-top{display:flex;align-items:center;gap:9px;padding:14px 18px;border-radius:17px 17px 0 0;background:rgba(255,255,255,.045);
 font-family:var(--fd);font-weight:800;font-size:10.5px;letter-spacing:.17em;text-transform:uppercase;color:#aebdc8}
.ty-steps{list-style:none;margin:0;padding:18px;display:grid;gap:11px}
.ty-steps li{position:relative;display:flex;align-items:flex-start;gap:12px;min-width:0;padding:14px 14px 14px 13px;border-radius:12px;
 background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.08)}
.ts-n{position:absolute;top:-7px;left:-7px;width:24px;height:24px;border-radius:50%;background:linear-gradient(180deg,var(--red-l),var(--red-d));
 color:#fff;display:grid;place-items:center;font-family:var(--fd);font-weight:900;font-size:12px;box-shadow:0 8px 16px -8px rgba(226,16,25,.9)}
.ts-ic{width:38px;height:38px;border-radius:10px;background:rgba(226,16,25,.16);border:1px solid rgba(226,16,25,.44);
 display:grid;place-items:center;color:var(--red-l);flex-shrink:0}
.ts-ic svg{width:18px;height:18px}
.ty-steps b{display:block;font-family:var(--fd);font-weight:800;font-size:14.5px;color:#fff;line-height:1.2}
.ty-steps i{display:block;font-style:normal;font-size:12.5px;color:#93a6b4;margin-top:5px;line-height:1.5}

.tyw{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:44px}
.tw{min-width:0;background:#fff;border:1px solid var(--line);border-radius:16px;padding:26px 22px 24px;box-shadow:var(--sh);transition:.26s}
.tw:hover{transform:translateY(-6px);border-color:var(--red);box-shadow:0 26px 54px -24px rgba(226,16,25,.35)}
.tw-ic{width:48px;height:48px;border-radius:12px;background:rgba(226,16,25,.1);border:1px solid rgba(226,16,25,.3);
 display:grid;place-items:center;color:var(--red);transition:.26s}
.tw-ic svg{width:22px;height:22px}
.tw:hover .tw-ic{background:var(--red);border-color:var(--red);color:#fff}
.tw h3{font-size:17px;color:var(--ink);margin-top:18px;text-transform:uppercase;line-height:1.2}
.tw p{font-size:14px;color:var(--tx2);margin-top:9px}
.ty-more{text-align:center;margin-top:34px}
.ty-more a{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:800;font-size:14px;letter-spacing:.04em;
 text-transform:uppercase;color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:11px;padding:14px 22px;box-shadow:var(--sh);transition:.2s}
.ty-more a:hover{transform:translateY(-3px);border-color:var(--red);color:var(--red)}
.ty-more svg{width:17px;height:17px}

@media(max-width:980px){.ty-in{grid-template-columns:minmax(0,1fr);gap:36px}.ty-next{justify-self:start;max-width:460px}}
@media(max-width:860px){.tyw{grid-template-columns:minmax(0,1fr)}}
@media(max-width:560px){.ty-next{max-width:none}}
@media (prefers-reduced-motion:reduce){.ty-tick{animation:none}}


